const COLORS={ink:'#172536',blue:'#2274b8',teal:'#00868c',orange:'#ff5533',green:'#318267',gray:'#8994a1',purple:'#7868a6'};
const steps=[
  ['Показатель','Определить, что именно измеряется',1],
  ['Сопоставимость','Проверить период и знаменатель',1],
  ['Сезонность','Последовательно удалить циклы',1],
  ['Прогноз','Проверить модель на будущем',1],
  ['Эксперимент','Оценить различие и неопределённость',1],
  ['Классификация','Получить матрицу маршрутизации',2],
  ['Безопасность','Сформировать матрицу контроля',2],
  ['Автоматизация','Формулы и продвинутая обработка',2],
  ['Пилот','Создать паспорт и презентацию',2]
];
const state={step:Math.min(8,Math.max(0,(+new URLSearchParams(location.search).get('step')||1)-1)),seasonStage:0,periodMode:'month',experimentStage:0,automation:'formula',excelLocale:'ru',securityScenario:'price',jti:null,gov:null};
const el=id=>document.getElementById(id),esc=s=>String(s??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[m]));
const parseJson=raw=>{const t=raw.trim().replace(/^```(?:json)?\s*/i,'').replace(/\s*```$/,''),start=t.indexOf('{');if(start<0)throw Error('Ответ не содержит объект JSON. Попросите ИИ-сервис вернуть только JSON.');let depth=0,quoted=false,escaped=false;for(let i=start;i<t.length;i++){const ch=t[i];if(quoted){if(escaped)escaped=false;else if(ch==='\\')escaped=true;else if(ch==='"')quoted=false;continue}if(ch==='"'){quoted=true;continue}if(ch==='{')depth++;if(ch==='}'&&--depth===0){const candidate=t.slice(start,i+1);try{return JSON.parse(candidate)}catch(first){try{return JSON.parse(candidate.replace(/,\s*([}\]])/g,'$1'))}catch(_){throw Error(`JSON не разобран: ${first.message}. Попросите ИИ-сервис исправить синтаксис и не добавлять пояснения.`)}}}}throw Error('Объект JSON не завершён. Попросите ИИ-сервис вернуть полный JSON.');};

function header(no,title,subtitle,kicker=state.step<5?'Занятие 1 · аналитика данных':'Занятие 2 · применение ИИ'){
  return `<header class="stage-head"><div class="kicker">${String(no).padStart(2,'0')} / ${kicker}</div><h2>${title}</h2><p>${subtitle}</p></header>`;
}
function lineChart(series,{height=390,min=null,max=null,zero=false,xLabels=[],xTitle='Период наблюдения',yTitle='Значение показателя'}={}){
  const W=1080,H=height,L=92,R=24,T=28,B=64,all=series.flatMap(s=>s.values.filter(Number.isFinite));
  let lo=min??Math.min(...all),hi=max??Math.max(...all),pad=(hi-lo||1)*.1;lo-=pad;hi+=pad;
  const n=Math.max(...series.map(s=>s.values.length)),X=i=>L+i/Math.max(1,n-1)*(W-L-R),Y=v=>T+(hi-v)/(hi-lo)*(H-T-B);
  let svg=`<svg class="chart" role="img" aria-label="${esc(yTitle)} по оси Y; ${esc(xTitle)} по оси X" viewBox="0 0 ${W} ${H}">`;
  for(let i=0;i<5;i++){const v=lo+(hi-lo)*i/4,y=Y(v);svg+=`<line x1="${L}" x2="${W-R}" y1="${y}" y2="${y}" stroke="#dce2e8"/><text x="72" y="${y+5}" text-anchor="end" font-size="12" fill="#637083">${v.toFixed(Math.abs(hi)<10?1:0)}</text>`}
  if(zero&&lo<0&&hi>0)svg+=`<line x1="${L}" x2="${W-R}" y1="${Y(0)}" y2="${Y(0)}" stroke="#172536" stroke-width="2"/>`;
  for(const s of series){const pts=s.values.map((v,i)=>Number.isFinite(v)?`${X(i)},${Y(v)}`:null).filter(Boolean).join(' ');svg+=`<polyline points="${pts}" fill="none" stroke="${s.color}" stroke-width="${s.width||3}" ${s.dash?'stroke-dasharray="8 6"':''}/>`}
  const ticks=[...new Set([0,Math.round((n-1)*.2),Math.round((n-1)*.4),Math.round((n-1)*.6),Math.round((n-1)*.8),n-1])];
  ticks.forEach(i=>{const label=xLabels[i]??String(i+1);svg+=`<line x1="${X(i)}" x2="${X(i)}" y1="${H-B}" y2="${H-B+5}" stroke="#8994a1"/><text x="${X(i)}" y="${H-B+20}" text-anchor="middle" font-size="11" fill="#637083">${esc(label)}</text>`});
  svg+=`<text x="${(L+W-R)/2}" y="${H-6}" text-anchor="middle" font-size="12" fill="#637083">${esc(xTitle)}</text><text x="16" y="${(T+H-B)/2}" text-anchor="middle" font-size="12" fill="#637083" transform="rotate(-90 16 ${(T+H-B)/2})">${esc(yTitle)}</text>`;
  svg+='</svg>';return svg;
}
function legend(items){return `<div class="actions">${items.map(x=>`<span style="border-bottom:4px solid ${x.color};padding:5px 8px;font-size:13px">${x.label}</span>`).join('')}</div>`}
function linearTrend(values){const n=values.length,xbar=(n-1)/2,ybar=values.reduce((a,b)=>a+b,0)/n,den=values.reduce((sum,_,i)=>sum+(i-xbar)**2,0),slope=values.reduce((sum,y,i)=>sum+(i-xbar)*(y-ybar),0)/den,intercept=ybar-slope*xbar;return{slope,values:values.map((_,i)=>intercept+slope*i)}}
function methodCard(title,body,sources=[]){return `<details class="method"><summary>${esc(title)}</summary><div class="method-body">${body}${sources.length?`<div class="source-list"><b>Основания и материалы</b>${sources.map(s=>`<a href="${esc(s.url)}" target="_blank" rel="noopener">${esc(s.label)}</a>`).join('')}</div>`:''}</div></details>`}
function copyButton(source,status){el(source).textContent&&navigator.clipboard.writeText(el(source).textContent).then(()=>{el(status).textContent='Скопировано';el(status).className='status ok'})}
function requireKeys(data,keys){const missing=keys.filter(k=>!(k in data));if(missing.length)throw Error('Не хватает полей: '+missing.join(', '));}
function requireList(data,key){if(!Array.isArray(data[key])||!data[key].length)throw Error(`Поле «${key}» должно быть непустым списком.`)}
function requireRows(data,key,keys){requireList(data,key);data[key].forEach((row,i)=>{if(!row||typeof row!=='object')throw Error(`Поле «${key}[${i}]» должно быть объектом.`);const missing=keys.filter(k=>!(k in row));if(missing.length)throw Error(`Не хватает полей: ${missing.map(k=>`${key}[${i}].${k}`).join(', ')}`)})}

function renderMetric(){
  const promptConfig={id:'metric-prompt-composer',title:'Карточка расчёта показателя',template:`Работайте только с обезличенными учебными данными.

Управленческий вопрос: [[question]]
Доступные столбцы: [[fields]]

Сформируйте карточку расчёта показателя. Отделите установленные правила от предположений. Верните только JSON:
{"name":"...","purpose":"...","numerator":"...","denominator":"...","period":"...","exclusions":["..."],"checks":["..."]}`,fields:[
    {key:'question',label:'Управленческий вопрос',selector:'[name=metric]',value:()=>document.querySelector('[name=metric]:checked').parentElement.textContent.trim()},
    {key:'fields',label:'Доступные столбцы',elementId:'metric-fields'}
  ]};
  el('stage').innerHTML=header(1,'Показатель начинается с управленческого вопроса','Один набор данных допускает несколько корректных расчётов. Выбор зависит от решения, которое должно быть принято.')+`<div class="stage-body two"><section class="panel"><h3>1. Выберите вопрос</h3><div class="choices">
    <label class="choice"><input type="radio" name="metric" value="share" checked>Какая доля завершённых обращений уложилась в установленный срок?</label>
    <label class="choice"><input type="radio" name="metric" value="median">Каков типичный полный срок обработки завершённого обращения?</label>
    <label class="choice"><input type="radio" name="metric" value="tail">В каких категориях сосредоточены самые длительные 10% обращений?</label>
  </div><label class="field"><b>Доступные столбцы</b><textarea id="metric-fields">идентификатор; дата регистрации; дата завершения; категория; канал; статус; целевой срок</textarea></label>${PromptComposer.markup(promptConfig)}${methodCard('Как составлена карточка расчёта',`<p><b>Карточка расчёта</b> — учебная форма этого практикума, а не название утверждённого государственного стандарта. Она помогает зафиксировать назначение показателя, числитель, знаменатель, период, исключения и проверки до начала расчёта.</p><ol><li>Сначала формулируется решение, для которого нужен показатель.</li><li>Затем однозначно задаются числитель и знаменатель.</li><li>После этого фиксируются период, исключения и контроль качества данных.</li></ol>`,[{label:'Росстат: методики расчёта показателей',url:'https://www.rosstat.gov.ru/met-pok'},{label:'Росстат: методологические разработки',url:'https://www.rosstat.gov.ru/folder/232427'}])}</section>
  <section class="panel soft"><h3>2. Получите карточку расчёта</h3><textarea class="response" id="metric-response" placeholder="Вставьте JSON из ИИ-сервиса"></textarea><div class="actions"><button class="button" id="metric-check">Построить карточку</button><button class="button secondary" id="metric-example">Учебный ответ</button></div><div id="metric-status" class="status"></div><div id="metric-artifact"></div></section></div>`;
  PromptComposer.bind(promptConfig.id);el('metric-example').onclick=()=>{el('metric-response').value=JSON.stringify({name:'Доля завершённых обращений в срок',purpose:'контроль соблюдения установленного срока',numerator:'завершённые обращения с длительностью не выше целевой',denominator:'все завершённые обращения выбранного периода',period:'полный календарный месяц по дате завершения',exclusions:['незавершённые обращения','записи без даты регистрации'],checks:['дубликаты идентификаторов','отрицательная длительность','сопоставимость полных периодов']},null,2)};
  el('metric-check').onclick=()=>{try{const d=parseJson(el('metric-response').value);requireKeys(d,['name','purpose','numerator','denominator','period','exclusions','checks']);requireList(d,'exclusions');requireList(d,'checks');el('metric-status').textContent='Структура принята';el('metric-status').className='status ok';el('metric-artifact').innerHTML=`<div class="artifact"><h3>${esc(d.name)}</h3><div class="artifact-grid"><div class="artifact-item"><b>Назначение</b>${esc(d.purpose)}</div><div class="artifact-item"><b>Период</b>${esc(d.period)}</div><div class="artifact-item"><b>Числитель</b>${esc(d.numerator)}</div><div class="artifact-item"><b>Знаменатель</b>${esc(d.denominator)}</div></div></div>`}catch(e){el('metric-status').textContent=e.message;el('metric-status').className='status bad'}};
}

function renderPeriod(){
  const months=['Янв','Фев','Мар','Апр','Май','Июн','Июл','Авг','Сен','Окт','Ноя','Дек'],days=[31,28,31,30,31,30,31,31,30,31,30,31],work=[15,20,21,22,19,20,23,21,22,23,20,22],closed=[860,980,1010,1050,920,970,1110,1040,1080,1160,1010,1140];
  const modes={month:{label:'Обращений за месяц',values:closed,thesis:'Месячный итог смешивает интенсивность работы и разное число рабочих дней.'},day:{label:'Обращений на рабочий день',values:closed.map((x,i)=>x/work[i]),thesis:'Приведение к рабочему дню меняет сравнение: январский спад почти исчезает.'},rolling:{label:'Индекс на сопоставимом 30-дневном окне',values:closed.map((x,i)=>x/days[i]*30),thesis:'Одинаковое окно пригодно для сравнения интенсивности, но не заменяет месячную отчётность.'}};
  const draw=()=>{const m=modes[state.periodMode];el('period-chart').innerHTML=lineChart([{values:m.values,color:COLORS.blue}],{xLabels:months,xTitle:'Месяц',yTitle:m.label});el('period-thesis').innerHTML=`<strong>${m.label}</strong>${m.thesis}`;document.querySelectorAll('[data-period]').forEach(b=>b.classList.toggle('active',b.dataset.period===state.periodMode))};
  el('stage').innerHTML=header(2,'Календарный месяц может исказить сравнение','Для отчётности нужен календарный итог; для оценки интенсивности — сопоставимый знаменатель.')+`<div class="stage-body"><div class="panel"><div class="chart-title"><b>Один ряд, три способа сравнения</b><span>обезличенный обучающий пример</span></div><div class="reveal"><button data-period="month">Календарный месяц</button><button data-period="day">На рабочий день</button><button data-period="rolling">30-дневное окно</button></div><div id="period-chart"></div><div class="thesis" id="period-thesis"></div>${methodCard('Как выполняется пересчёт',`<dl class="formula-list"><div><dt>Календарный итог</dt><dd>Сумма завершённых обращений внутри календарного месяца.</dd></div><div><dt>На рабочий день</dt><dd>Календарный итог ÷ число рабочих дней месяца.</dd></div><div><dt>Сопоставимое окно</dt><dd>Календарный итог ÷ число календарных дней × 30.</dd></div></dl><p>Учебный пересчёт показывает влияние знаменателя. Он не заменяет утверждённую методику конкретного показателя.</p>`,[{label:'Росстат: методики расчёта показателей',url:'https://www.rosstat.gov.ru/met-pok'}])}</div><div class="profile-grid"><div class="profile"><b>Для обязательной отчётности</b>Сохраняйте календарный месяц.</div><div class="profile"><b>Для производительности</b>Учитывайте рабочие дни и доступный ресурс.</div><div class="profile"><b>Для динамики</b>Используйте одинаковые скользящие окна.</div></div></div>`;
  document.querySelectorAll('[data-period]').forEach(b=>b.onclick=()=>{state.periodMode=b.dataset.period;draw()});draw();
}

function renderSeason(){
  const d=state.gov,rows=d.rows.slice(-d.focus_days),stages=[
    ['Наблюдаемый ряд показывает рост','За последние 35 дней линия тренда направлена вверх. По этому фрагменту можно преждевременно сделать вывод об устойчивом росте.','observed','Исходный ряд'],
    ['После учёта годового цикла виден спад','Годовой профиль оценён по семилетней истории. После его исключения направление тренда меняется.','without_annual','− годовой цикл'],
    ['После учёта ритма внутри месяца снова виден рост','Дни внутри месяца дают повторяющийся профиль нагрузки. Его исключение вновь меняет управленческий вывод.','without_monthly','− внутримесячный цикл'],
    ['Недельный цикл раскрывает итоговый слабый спад','После исключения различий между днями недели остаётся базовая динамика: небольшое снижение, а не первоначальный рост.','baseline','− недельный цикл']
  ],s=stages[state.seasonStage],values=rows.map(r=>r[s[2]]),raw=rows.map(r=>r.observed),dates=rows.map(r=>r.date.slice(5)),trend=linearTrend(values),trendColor=trend.slope>=0?COLORS.green:COLORS.orange,trendWord=trend.slope>=0?'рост':'снижение';
  el('stage').innerHTML=header(3,'Повторяющиеся циклы меняют вывод о динамике','Государственный показатель рассматривается на обезличенном обучающем ряде из 2 557 ежедневных наблюдений 2019–2025 годов.')+`<div class="stage-body"><div class="panel"><div class="reveal">${stages.map((x,i)=>`<button data-season="${i}" class="${i===state.seasonStage?'active':''}">${i+1}. ${x[3]}</button>`).join('')}</div><div class="chart-title"><b>${s[0]}</b><span>последние 35 дней семилетнего ряда</span></div>${legend([{label:state.seasonStage?'Скорректированный ряд':'Наблюдаемый ряд',color:state.seasonStage?COLORS.blue:COLORS.ink},{label:`Линия тренда: ${trendWord}`,color:trendColor}])}${lineChart(state.seasonStage?[{values:raw,color:'#c9d0d7',width:2},{values,color:COLORS.blue,width:3},{values:trend.values,color:trendColor,width:5,dash:true}]:[{values:raw,color:COLORS.ink,width:3},{values:trend.values,color:trendColor,width:5,dash:true}],{xLabels:dates,xTitle:'Дата наблюдения',yTitle:'Завершённые обращения за день'})}<div class="trend-result ${trend.slope>=0?'up':'down'}"><span>${trend.slope>=0?'↗':'↘'}</span><div><b>${trendWord[0].toUpperCase()+trendWord.slice(1)}: ${Math.abs(trend.slope).toFixed(2)} обращения в день</b><small>наклон линейной тенденции на показанном отрезке</small></div></div><div class="thesis"><strong>${s[0]}</strong>${s[1]}</div>${methodCard('Как устроен учебный расчёт',`<ol><li>Наблюдаемый ряд представлен как сумма базовой динамики, годового, внутримесячного и недельного циклов.</li><li>Профили циклов оцениваются на семилетней истории, а на графике показаны последние 35 дней.</li><li>На каждом шаге один профиль вычитается из ряда, после чего линия тренда рассчитывается заново методом наименьших квадратов.</li><li>Смена цвета показывает смену направления, но не доказывает причину изменения.</li></ol><p>Все значения созданы для обучения и не относятся к реальному ведомству или территории.</p>`,[{label:'Росстат: сезонная корректировка временных рядов',url:'https://www.rosstat.gov.ru/storage/mediabank/prez-191119.pdf'},{label:'Скачать полный обучающий ряд',url:'downloads/seasonality_government_training.csv'}])}</div><div class="instruction"><b>Сюжетный поворот:</b> каждый следующий слой меняет знак краткосрочной тенденции. Управленческий вывод делается после проверки циклов и на полном сопоставимом периоде.</div></div>`;
  document.querySelectorAll('[data-season]').forEach(b=>b.onclick=()=>{state.seasonStage=+b.dataset.season;render()});
}

function renderForecast(){
  el('stage').innerHTML=header(4,'Прогноз проверяется на данных, которых модель ещё не видела','Используем открытый ряд просмотров Wikimedia и обезличенный многолетний учебный ряд сервиса.')+`<div class="stage-body"><div class="instruction"><b>Порядок работы:</b> передвиньте границу истории, выберите прогноз, затем откройте следующие 90 дней и сравните ошибки. Сезонная модель не обязана побеждать на каждом наборе.</div><iframe class="forecast-frame" title="Тренажёр прогнозирования" src="https://wybaeb.github.io/data-literacy-forecast-lab/"></iframe><p class="status">Если встроенное окно не открылось, <a href="https://wybaeb.github.io/data-literacy-forecast-lab/" target="_blank" rel="noopener">откройте тренажёр прогнозирования в новой вкладке</a>.</p></div>`;
}

function experimentCI(days){
  const rows=state.jti.experiment.daily.slice(9,9+days),n=120*days,a=rows.reduce((s,r)=>s+Math.round(r.ad_promo_rate*120),0),b=rows.reduce((s,r)=>s+Math.round(r.control_promo_rate*120),0),pa=a/n,pb=b/n,d=pa-pb,se=Math.sqrt(pa*(1-pa)/n+pb*(1-pb)/n);return{n,a,b,pa,pb,d,lo:d-1.96*se,hi:d+1.96*se};
}
function renderExperiment(){
  const e=state.jti.experiment,stages=[
    ['Рост совпал с двумя изменениями','Одновременно с новым порядком предварительной проверки увеличили число сотрудников. По общей динамике нельзя отделить одно влияние от другого.'],
    ['В контрольной группе виден похожий рост','Учебные обращения заранее распределены между новым и действующим порядком. Одинаковое изменение условий затрагивает обе группы.'],
    ['Ранний лидер меняется по мере накопления данных','Через 5 дней впереди действующий порядок, через 10 дней различия почти нет, через 15 дней впереди новый.'],
    ['Интервал включает отсутствие различия','Наблюдаемое различие +1,8 п.п. совместимо и с небольшим отрицательным, и с положительным эффектом нового порядка.']
  ],s=stages[state.experimentStage],rows=e.daily;
  let chart,extra='';
  const dayLabels=rows.map(r=>`День ${r.day}`);
  if(state.experimentStage===0)chart=lineChart([{values:rows.map(r=>r.sales),color:COLORS.blue},{values:rows.map(r=>r.promo),color:COLORS.orange}],{xLabels:dayLabels,xTitle:'День наблюдения',yTitle:'Принято с первого раза, обращений'});
  if(state.experimentStage===1)chart=lineChart([{values:rows.map(r=>r.ad_sales),color:COLORS.blue},{values:rows.map(r=>r.control_sales),color:COLORS.teal}],{xLabels:dayLabels,xTitle:'День наблюдения',yTitle:'Принято с первого раза, обращений'});
  if(state.experimentStage>=2){const spans=[5,10,15],cards=spans.map((n,i)=>{const c=experimentCI(n);return `<button data-exp-days="${n}" class="${n===(state.expDays||5)?'active':''}">${['5 дней','10 дней','15 дней'][i]}<br><b>${(c.d*100).toFixed(1)} п.п.</b></button>`}).join('');const c=experimentCI(state.expDays||5),toX=v=>(v+0.08)/.16*100;chart=lineChart([{values:rows.slice(9).map(r=>r.ad_promo_rate*100),color:COLORS.blue},{values:rows.slice(9).map(r=>r.control_promo_rate*100),color:COLORS.teal}],{xLabels:dayLabels.slice(9),xTitle:'День эксперимента',yTitle:'Доля целевого результата, %'});extra=`<div class="reveal">${cards}</div><div class="metric-row"><div class="metric">Вариант A<b>${(c.pa*100).toFixed(1)}%</b>${c.a} из ${c.n}</div><div class="metric">Вариант B<b>${(c.pb*100).toFixed(1)}%</b>${c.b} из ${c.n}</div><div class="metric">Различие<b>${c.d>=0?'+':''}${(c.d*100).toFixed(1)} п.п.</b></div></div><div class="ci-scale"><div class="ci-band" style="left:${toX(c.lo)}%;width:${toX(c.hi)-toX(c.lo)}%"></div><div class="ci-point" style="left:${toX(c.d)}%"></div></div><div class="ci-labels"><span>−8 п.п.</span><span>0</span><span>+8 п.п.</span></div><p><b>95% интервал:</b> ${(c.lo*100).toFixed(1)}…+${(c.hi*100).toFixed(1)} п.п.</p>`}
  el('stage').innerHTML=header(5,'Наблюдаемое различие нужно отделить от случайного разброса','Разбираем обезличенный учебный эксперимент на 11 520 обращениях, заранее распределённых между двумя порядками работы.')+`<div class="stage-body"><div class="panel"><div class="reveal">${stages.map((x,i)=>`<button data-experiment="${i}" class="${i===state.experimentStage?'active':''}">${i+1}. ${['Совпадение','Контроль','Накопление','Вывод'][i]}</button>`).join('')}</div><div class="chart-title"><b>${s[0]}</b><span>обезличенный учебный эксперимент</span></div>${legend(state.experimentStage===0?[{label:'Все обращения, принятые с первого раза',color:COLORS.blue},{label:'Обращения по новому порядку',color:COLORS.orange}]:[{label:'Новый порядок',color:COLORS.blue},{label:'Действующий порядок',color:COLORS.teal}])}${chart}${extra}<div class="thesis"><strong>${s[0]}</strong>${s[1]}</div>${methodCard('Как читать доверительный интервал',`<ol><li>До запуска фиксируются показатель, минимально значимое различие, срок и правило остановки.</li><li>Обезличенные учебные обращения распределяются между сопоставимыми группами независимо от ожидаемого результата.</li><li>Для разности долей рассчитывается оценка и 95%-й доверительный интервал.</li><li>Если интервал включает ноль, данных недостаточно для вывода о направлении эффекта.</li></ol><p>Повторная проверка «до появления нужного результата» повышает риск ложного вывода. Эксперимент не заменяет правовую и организационную оценку изменения процесса.</p>`,[{label:'Росстат: выборочный метод наблюдения',url:'https://www.rosstat.gov.ru/bgd/free/B99_10/IssWWW.exe/Stg/d020/i020030r.htm'},{label:'Росстат: расчёт доверительного интервала',url:'https://www.rosstat.gov.ru/bgd/regl/b08_102/IssWWW.exe/Stg/d01/met.htm'}])}</div><div class="instruction">Решение фиксируется до эксперимента: показатель, минимально значимое различие, объём выборки и правило остановки. Просмотр промежуточного лидера не заменяет заранее заданный план.</div></div>`;
  document.querySelectorAll('[data-experiment]').forEach(b=>b.onclick=()=>{state.experimentStage=+b.dataset.experiment;render()});document.querySelectorAll('[data-exp-days]').forEach(b=>b.onclick=()=>{state.expDays=+b.dataset.expDays;render()});
}

const codeRules={formula:[['Проверка пустых дат',/(?:\b(?:OR|AND|ISBLANK|COUNTBLANK)\s*\(|[BC]2\s*(?:=|<>)\s*"")/i],['Защита от отрицательного срока',/(?:\bMAX\s*\(|(?:C2\s*-\s*B2|H2)\s*<\s*0)/i],['Сравнение с целевым сроком',/(?:\$?H2\s*<=\s*\$?G2|\$?G2\s*>=\s*\$?H2)/i],['Подсчёт доли',/COUNTIF\s*\(/i]],excel:[['Option Explicit',/\bOption\s+Explicit\b/i],['ProcessTrainingAppeals',/Public\s+Sub\s+ProcessTrainingAppeals\s*\(/i],['Пакетное чтение',/CurrentRegion\.Value2?/i],['Словарь повторов',/Scripting\.Dictionary/i],['Разбор дат',/DateSerial\s*\(/i],['Диаграмма',/ChartObjects\.Add/i]],sheets:[['processTrainingAppeals',/function\s+processTrainingAppeals\s*\(/i],['Единый диапазон',/getDataRange\s*\(/i],['Пакетное чтение',/getValues\s*\(/i],['Пакетная запись',/setValues\s*\(/i],['Множество повторов',/new\s+Set\s*\(/i],['Диаграмма',/newChart\s*\(/i]]};
function automationPrompt(kind){if(kind==='excel')return `Напишите полный модуль VBA для обезличенной учебной выгрузки «Выгрузка» на 12 324 строки. Поля: ID обращения, дата регистрации, дата завершения, канал, категория, статус, целевой срок, территориальная группа, краткое содержание. Удалите полные повторы по исходным значениям до преобразований; явно разберите даты ДД.ММ.ГГГГ и ГГГГ-ММ-ДД через DateSerial; нормализуйте четыре канала; добавьте длительность и соблюдение срока; создайте лист «Сводка» и диаграмму. Обязательные требования: Option Explicit; точка входа Public Sub ProcessTrainingAppeals(); одно чтение CurrentRegion.Value2; обработка данных в памяти; Scripting.Dictionary; одна пакетная запись. Верните только полный код VBA.`;return `Напишите полный Google Apps Script для той же обезличенной учебной выгрузки. Удалите полные повторы до преобразований, разберите два формата дат, нормализуйте каналы, добавьте длительность и соблюдение срока, создайте лист «Сводка» и диаграмму. Обязательные требования: функция processTrainingAppeals(); один getDataRange и getValues; обработка данных в памяти с new Set; одна запись setValues; диаграмма newChart. Верните только полный код.`}

const excelLocales={
  ru:{label:'Российские настройки',short:'; аргументы · , дробная часть',argument:';',decimal:',',reference:'reference_excel_formulas_ru.txt'},
  international:{label:'Международные настройки',short:', аргументы · . дробная часть',argument:',',decimal:'.',reference:'reference_excel_formulas_international.txt'}
};
function automationPromptLocalized(kind){
  if(kind==='formula'){
    const locale=excelLocales[state.excelLocale];
    return `Для листа Excel «Формулы» предложите три формулы: 1) в H2 длительность между датой завершения C2 и датой регистрации B2; пустые даты должны давать пустой результат, отрицательная длительность — 0; 2) в I2 «Да», если длительность H2 не превышает целевой срок G2, иначе «Нет»; 3) доля непустых результатов I2:I121 со значением «Да». Используйте только английские имена функций IF, OR, MAX и COUNTIF. Региональные настройки Excel: разделитель аргументов — «${locale.argument}», десятичный знак — «${locale.decimal}». Во всех формулах строго соблюдайте эти два знака; не заменяйте разделитель аргументов знаком другого режима. Формула H2 обязана содержать проверку OR(B2=""${locale.argument}C2="") и защиту MAX(0${locale.argument}C2-B2). Если появятся дробные константы, записывайте их с десятичным знаком «${locale.decimal}». Перед ответом проверьте каждый разделитель. Верните только три полные формулы с краткими названиями.`;
  }
  return automationPrompt(kind);
}
function renderAutomationLocalized(){
  const k=state.automation,isFormula=k==='formula',isExcel=k==='excel',locale=excelLocales[state.excelLocale];
  const localeRules=state.excelLocale==='ru'
    ? [['Разделитель аргументов «;»',/(?:IF|OR|COUNTIF)\([^\r\n)]*;/i],['Десятичный знак — запятая',code=>!/[0-9]\.[0-9]/.test(code)]]
    : [['Разделитель аргументов «,»',/(?:IF|OR|COUNTIF)\([^\r\n)]*,/i],['Десятичный знак — точка',code=>!/[0-9],[0-9]/.test(code)]];
  const rules=isFormula?[...codeRules.formula,...localeRules]:codeRules[k];
  const file=isFormula?'uchebny_nabor_formuly_excel.xlsm':isExcel?'obrashcheniya_12000_excel.xlsm':'obrashcheniya_12000_google.csv';
  const reference=isFormula?locale.reference:isExcel?'reference_process_appeals.bas':'reference_process_appeals.gs';
  const promptConfig={id:'auto-prompt-composer',title:isFormula?'Формулы для Excel':isExcel?'Модуль VBA для Excel':'Сценарий для Google Таблиц',template:automationPromptLocalized(k),fields:[]};
  const localeControl=isFormula?`<section class="excel-locale" aria-label="Региональные настройки Excel"><div><b>Региональные настройки Excel</b><span>По умолчанию: аргументы через точку с запятой, дробная часть через запятую.</span></div><div class="segmented">${Object.entries(excelLocales).map(([key,value])=>`<button type="button" data-excel-locale="${key}" class="${key===state.excelLocale?'active':''}">${value.label}<small>${value.short}</small></button>`).join('')}</div></section>`:'';
  el('stage').innerHTML=header(8,isFormula?'Расчёт начинается с прозрачных формул':'Большой набор данных обрабатывается программой, а не сообщением модели',isFormula?'Сначала участник проверяет логику на 120 строках; программирование применяется после того, как расчёт понятен.':'ИИ формирует программу; Excel или Google Таблицы выполняют её локально на полном обезличенном наборе.')+`<div class="stage-body"><div class="tabs"><button data-auto="formula" class="${isFormula?'active':''}">1. Формулы Excel</button><button data-auto="excel" class="${isExcel?'active':''}">2. VBA · продвинутая практика</button><button data-auto="sheets" class="${k==='sheets'?'active':''}">3. Google Таблицы</button></div>${localeControl}<div class="two"><section class="panel warm"><h3>1. Скачайте учебный набор</h3><p>${isFormula?'120 строк с распознанными датами в книге XLSM. Формат уже поддерживает макросы, пересохранять файл не нужно.':isExcel?'12 324 строки с повторами, двумя форматами дат и вариантами написания каналов. Книга уже имеет формат XLSM.':'12 324 строки в CSV для загрузки в Google Таблицы.'}</p><div class="actions"><a class="button" download href="downloads/${file}">Скачать ${isFormula||isExcel?'книгу XLSM':'CSV'}</a><a class="button secondary" download href="downloads/${reference}">Эталон преподавателя</a></div><h3>2. Передайте задачу ИИ-сервису</h3>${PromptComposer.markup(promptConfig)}</section><section class="panel"><h3>3. Проверьте полученный ${isFormula?'расчёт':'код'}</h3><textarea class="response" id="auto-code" placeholder="Вставьте ${isFormula?'формулы':'полный код'}"></textarea><div class="actions"><button class="button" id="auto-check">Проверить требования</button><button class="button secondary" id="auto-reference">Подставить эталон</button></div><div id="auto-status" class="status"></div><div id="auto-results" class="code-checks"></div></section></div><div class="instruction">${isFormula?`Текущий режим: ${locale.label.toLowerCase()} — «${locale.argument}» между аргументами и «${locale.decimal}» в дробной части. Формулы позволяют проверить каждое правило до автоматизации полного набора.`:'Модель создаёт программу, а табличный редактор применяет её ко всему набору. VBA и Google Apps Script относятся к продвинутой части второго занятия.'}</div></div>`;
  document.querySelectorAll('[data-auto]').forEach(button=>button.onclick=()=>{state.automation=button.dataset.auto;render()});
  document.querySelectorAll('[data-excel-locale]').forEach(button=>button.onclick=()=>{state.excelLocale=button.dataset.excelLocale;render()});
  PromptComposer.bind(promptConfig.id);
  const validate=()=>{const code=el('auto-code').value,checks=rules.map(([label,test])=>[label,test instanceof RegExp?test.test(code):test(code)]);el('auto-results').innerHTML=checks.map(([label,ok])=>`<div class="check ${ok?'pass':'fail'}">${ok?'✓':'✕'} ${label}</div>`).join('');const missing=checks.filter(item=>!item[1]).map(item=>item[0]);el('auto-status').textContent=missing.length?'Требуется исправить: '+missing.join(', '):'Все обязательные признаки найдены';el('auto-status').className='status '+(missing.length?'bad':'ok')};
  el('auto-check').onclick=validate;
  el('auto-reference').onclick=async()=>{el('auto-code').value=await fetch(`downloads/${reference}`).then(response=>response.text());validate()};
}

function renderClassification(){const appeals='EDU-001 | Запрос о порядке предоставления услуги | Портал\nEDU-002 | Сообщение о состоянии объекта общего пользования | Контакт-центр\nEDU-003 | Предложение об изменении маршрута обслуживания | Письмо',promptConfig={id:'class-prompt-composer',title:'Предварительная классификация',template:`Классифицируйте только приведённые обезличенные учебные обращения:\n[[appeals]]\n\nКатегории: благоустройство; транспортная доступность; социальная поддержка; иное. При уверенности ниже 0.70 укажите маршрут «проверка сотрудником». Верните только один корректный JSON-объект. В массиве items должно быть ровно три объекта — по одному на каждый ID. В КАЖДОМ объекте обязательны четыре поля: id, category, confidence и reason; reason — краткое основание, его нельзя пропускать. Структура: {"items":[{"id":"EDU-001","category":"...","confidence":0.0,"reason":"краткое основание"}],"escalation":[{"condition":"...","route":"..."}]}`,fields:[{key:'appeals',label:'Обращения для классификации',value:appeals}]};el('stage').innerHTML=header(6,'ИИ предлагает категорию, сотрудник утверждает маршрут','Структурированный ответ превращается в матрицу маршрутизации; записи с низкой уверенностью направляются на проверку.')+`<div class="stage-body two"><section class="panel"><h3>Учебные обращения</h3><div class="matrix"><div class="matrix-row matrix-head"><b>ID</b><b>Обезличенный текст</b><b>Канал</b></div><div class="matrix-row"><span>EDU-001</span><span>Запрос о порядке предоставления услуги</span><span>Портал</span></div><div class="matrix-row"><span>EDU-002</span><span>Сообщение о состоянии объекта общего пользования</span><span>КЦ</span></div><div class="matrix-row"><span>EDU-003</span><span>Предложение об изменении маршрута обслуживания</span><span>Письмо</span></div></div>${PromptComposer.markup(promptConfig)}</section><section class="panel soft"><h3>Ответ → матрица</h3><textarea class="response" id="class-response"></textarea><div class="actions"><button class="button" id="class-build">Построить матрицу</button><button class="button secondary" id="class-example">Учебный ответ</button></div><div id="class-status" class="status"></div><div id="class-artifact"></div></section></div>`;PromptComposer.bind(promptConfig.id);el('class-example').onclick=()=>{el('class-response').value=JSON.stringify({items:[{id:'EDU-001',category:'социальная поддержка',confidence:.62,reason:'недостаточно содержания для точного назначения'},{id:'EDU-002',category:'благоустройство',confidence:.91,reason:'состояние объекта общего пользования'},{id:'EDU-003',category:'транспортная доступность',confidence:.87,reason:'изменение маршрута'}],escalation:[{condition:'confidence < 0.70',route:'проверка сотрудником'}]},null,2)};el('class-build').onclick=()=>{try{const d=parseJson(el('class-response').value);requireKeys(d,['items','escalation']);requireRows(d,'items',['id','category','confidence','reason']);requireRows(d,'escalation',['condition','route']);if(d.items.length!==3)throw Error('Поле «items» должно содержать ровно три результата — по одному на каждый ID.');const invalid=d.items.findIndex(x=>typeof x.confidence!=='number'||x.confidence<0||x.confidence>1);if(invalid>=0)throw Error(`Поле «items[${invalid}].confidence» должно быть числом от 0 до 1.`);el('class-artifact').innerHTML=`<div class="matrix"><div class="matrix-row matrix-head"><b>ID</b><b>Категория</b><b>Уверенность</b></div>${d.items.map(x=>`<div class="matrix-row"><span>${esc(x.id)}</span><span>${esc(x.category)}${x.confidence<.7?' · проверка сотрудником':''}</span><span>${Math.round(x.confidence*100)}%</span></div>`).join('')}</div>`;el('class-status').textContent='Матрица построена';el('class-status').className='status ok'}catch(e){el('class-status').textContent=e.message;el('class-status').className='status bad'}}}

const securityScenarios={
  price:{label:'Сравнить цены',situation:'Определить ориентир средней стоимости стандартного офисного товара перед подготовкой обоснования закупки.',data:'Опубликованные характеристики и цены из открытых карточек товаров; без данных личных кабинетов, заказов и поставщиков из внутренних документов.',volume:'Около 100 открытых карточек товаров, однократное исследование.',transfer:'Передать перечень открытых характеристик и цен в доступный ИИ-сервис для группировки и расчёта.',purpose:'Получить черновой диапазон цен; сотрудник проверяет источники и выполняет расчёт по утверждённой методике.',unknowns:'Условия использования выбранного сервиса и локальные правила организации.',level:'открытые сведения',type:'Опубликованные характеристики и цены товаров без данных ограниченного доступа.',storage:'По утверждённому для выбранного сервиса порядку; внутренние и персональные данные не передаются.',use:'Допустимо использовать результат только как проверяемый черновой расчёт.',decision:'Допустимо: передаются только открытые сведения, условия сервиса проверены',basis:'149-ФЗ; локальные акты; условия использования источников и сервиса'},
  birthday:{label:'Поздравить сотрудников',situation:'Подготовить список сотрудников, которых нужно поздравить с днём рождения в мае, и черновики поздравлений.',data:'Фамилии, имена, подразделения и полные даты рождения сотрудников государственного учреждения.',volume:'Таблица примерно на 350 сотрудников; повторяется ежемесячно.',transfer:'Загрузить рабочую таблицу в общедоступный ИИ-сервис через личную учётную запись.',purpose:'Отобрать майские даты и подготовить персональные тексты; результат использует сотрудник кадрового подразделения.',unknowns:'Правовое основание, минимально необходимый состав полей, поручение на обработку, место хранения и удаление истории запросов.',level:'персональные данные',type:'ФИО, место работы и даты рождения сотрудников.',storage:'Только в утверждённой информационной системе и в пределах установленного срока.',use:'Доступ по роли; для поздравления достаточно минимального состава данных без полной даты рождения.',decision:'Только в согласованном контуре при наличии правового основания',basis:'152-ФЗ; ПП РФ № 1119; локальные акты оператора'},
  appeal:{label:'Подготовить ответ',situation:'Сократить текст обращения жителя и подготовить проект ответа для последующей проверки сотрудником.',data:'ФИО, телефон, адрес, номер обращения и описание семейной ситуации заявителя.',volume:'Одно обращение сейчас; в дальнейшем возможно до 40 обращений в день.',transfer:'Скопировать текст обращения из ведомственной системы в ИИ-сервис подрядчика.',purpose:'Выделить вопрос, обязательства и срок ответа; окончательное решение принимает сотрудник.',unknowns:'Договор с подрядчиком, место обработки, журналирование, сроки хранения и порядок удаления.',level:'персональные данные',type:'Идентификаторы, контакты и содержание обращения, позволяющее определить заявителя.',storage:'В утверждённом контуре с установленными сроками хранения и разграничением доступа.',use:'Сотрудник проверяет проект; модель не принимает решение по обращению.',decision:'Только после согласования контура и условий обработки',basis:'152-ФЗ; ПП РФ № 1119; применимые требования к государственной информационной системе'},
  health:{label:'Составить график',situation:'Составить график индивидуальных приёмов для получателей меры поддержки и предложить продолжительность консультаций.',data:'ФИО, сведения об инвалидности, заключения о состоянии здоровья и назначенные меры поддержки.',volume:'45 записей на следующую неделю.',transfer:'Загрузить таблицу в новый облачный сервис для автоматического составления расписания.',purpose:'Снизить число накладок в расписании; график утверждает руководитель подразделения.',unknowns:'Основание обработки специальных категорий данных, допустимый состав, контур и меры защиты.',level:'специальные категории персональных данных',type:'Сведения о здоровье и инвалидности вместе с идентификаторами граждан.',storage:'Только в специально разрешённом контуре с установленным уровнем защищённости.',use:'Требуется минимизация данных и отдельная проверка основания, доступа и мер защиты.',decision:'Стоп до письменного согласования условий обработки',basis:'152-ФЗ; ПП РФ № 1119; применимые требования ФСТЭК'},
  memo:{label:'Сократить записку',situation:'Сделать краткую справку из проекта служебной записки для обсуждения на внутреннем совещании.',data:'Неопубликованные сведения о ходе ведомственного проекта, внутренних сроках и замечаниях к работе подрядчика.',volume:'Документ на 18 страниц и три внутренних приложения.',transfer:'Вставить текст в внешний ИИ-сервис для реферирования.',purpose:'Получить тезисы к совещанию; сотрудник проверяет формулировки.',unknowns:'Кто является обладателем информации, установлен ли режим ограничения доступа и разрешена ли передача подрядчику.',level:'информация ограниченного доступа',type:'Неопубликованные служебные материалы, доступ к которым может быть ограничен обладателем информации.',storage:'В ведомственной информационной системе с установленными мерами защиты.',use:'Только после определения состава сведений, допустимого контура и прав доступа.',decision:'Стоп до решения обладателя информации и специалиста по ИБ',basis:'149-ФЗ; локальные акты; приказ ФСТЭК России № 117, если применим'},
  secret:{label:'Подготовить тезисы',situation:'Подготовить одностраничные тезисы по приложению к документу, на первой странице которого стоит гриф «Секретно».',data:'Текст приложения, регистрационный номер и описанные в нём сведения; цель — только сократить объём документа.',volume:'Четыре страницы одного документа.',transfer:'Скопировать текст в привычный ИИ-сервис, чтобы быстрее подготовиться к совещанию.',purpose:'Получить краткое изложение; дальнейшее использование предполагается внутри организации.',unknowns:'Допустимый специализированный контур и решение режимно-секретного подразделения.',level:'сведения, составляющие государственную тайну',type:'Сведения из документа с установленным грифом секретности.',storage:'Только по режиму государственной тайны и внутренним требованиям организации.',use:'Решение принимает уполномоченное подразделение; учебный и общедоступный сервисы не используются.',decision:'Запрещено в данном учебном сценарии',basis:'Закон РФ № 5485-1; специальные режимные требования'}
};
function securityTransferRule(s){if(s.level==='открытые сведения')return 'Возможна передача только открытых сведений после проверки условий сервиса и локальных правил.';if(s.level.includes('государственную'))return 'Не передавать вне специально предназначенного контура без решения уполномоченного подразделения.';if(s.level.includes('ограниченного'))return 'Не передавать внешнему исполнителю до решения обладателя информации и проверки договора.';return 'Не передавать в общедоступный или не согласованный сервис до подтверждения основания и условий обработки.'}
function securityExample(s){return `| Уровень | Категория сведений | Значимость | Допустимый контур | Передача | Хранение | Решение | Нормативное основание |\n|---|---|---|---|---|---|---|---|\n| ${s.level} | ${s.type} | ${s.level==='открытые сведения'?'обычная':s.level.includes('государственную')?'критическая':'повышенная'} | ${s.storage} | ${securityTransferRule(s)} | ${s.storage} | ${s.decision} | ${s.basis} |\n\n| Раздел | Пункт |\n|---|---|\n| НЕ ДЕЛАТЬ | Не вводить реальные закрытые сведения в сервис до подтверждения допустимого контура. |\n| НЕ ДЕЛАТЬ | Не считать торговое наименование или страну поставщика достаточным основанием для решения. |\n| СДЕЛАТЬ | Зафиксировать цель, минимально необходимый состав данных и роль сотрудника. |\n| СДЕЛАТЬ | Проверить договор, размещение, доступ, журналирование, сроки хранения и удаление. |\n| ВОПРОСЫ СПЕЦИАЛИСТУ | Кто является обладателем информации и оператором персональных данных? |\n| ВОПРОСЫ СПЕЦИАЛИСТУ | Какой контур письменно разрешён для этой категории сведений? |\n| ВОПРОСЫ СПЕЦИАЛИСТУ | Какие стоп-условия и порядок реагирования утверждены? |`}
function securityRoute(value){const text=String(value||'').toLocaleLowerCase('ru-RU');if(/запрещ|стоп|нельзя|не передав|приостанов/.test(text))return{tone:'red',label:'Остановиться и согласовать'};if(/^допустим/.test(text)&&!/согласов|при наличии|после подтвержд/.test(text))return{tone:'green',label:'Можно продолжить после обычной проверки'};if(/только|согласован|согласов|при наличии|после подтвержд/.test(text))return{tone:'amber',label:'Только при выполнении условий'};if(/допустим|можно|разреш/.test(text))return{tone:'green',label:'Можно продолжить после обычной проверки'};return{tone:'amber',label:'Требуется уточнение условий'}}
function parseSecurityMarkdown(raw){
  const text=raw.trim().replace(/^```(?:markdown|md)?\s*/i,'').replace(/\s*```$/,''),lines=text.split(/\r?\n/),tableStart=lines.findIndex(line=>/^\s*\|/.test(line)&&/Уровень/i.test(line)&&/Решение/i.test(line));
  if(tableStart<0)throw Error('Не найдена таблица с колонками «Уровень» и «Решение». Попросите ИИ-сервис вернуть ответ по шаблону.');
  const clean=value=>value.replace(/[*_`]/g,'').replace(/\s+/g,' ').trim(),split=line=>line.trim().replace(/^\||\|$/g,'').split('|').map(x=>clean(x)),headers=split(lines[tableStart]),required=['Уровень','Категория сведений','Значимость','Допустимый контур','Передача','Хранение','Решение','Нормативное основание'],missing=required.filter(x=>!headers.includes(x));
  if(missing.length)throw Error('В таблице не хватает колонок: '+missing.join(', ')+'.');
  const rows=[];for(let i=tableStart+2;i<lines.length&&/^\s*\|/.test(lines[i]);i++){const values=split(lines[i]);if(values.length<headers.length)continue;rows.push(Object.fromEntries(headers.map((h,j)=>[h,values[j]])))}
  if(!rows.length)throw Error('В таблице нет строки с результатом.');
  if(rows.length!==1)throw Error('В первой таблице должна быть ровно одна строка результата по описанной ситуации.');
  const actionStart=lines.findIndex(line=>/^\s*\|/.test(line)&&split(line).length===2&&split(line)[0].toLocaleLowerCase('ru-RU')==='раздел'&&split(line)[1].toLocaleLowerCase('ru-RU')==='пункт'),actions={};
  if(actionStart>=0){for(let i=actionStart+2;i<lines.length&&/^\s*\|/.test(lines[i]);i++){const values=split(lines[i]);if(values.length<2||!values[1])continue;const key=values[0].toLocaleUpperCase('ru-RU');(actions[key]??=[]).push(values[1])}}
  const heading=line=>clean(line.replace(/^#{1,6}\s*/, '').replace(/:$/, '')).toLocaleUpperCase('ru-RU'),section=name=>{if(actions[name])return actions[name];const start=lines.findIndex(line=>heading(line)===name);if(start<0)return[];const result=[];for(let i=start+1;i<lines.length;i++){if(['НЕ ДЕЛАТЬ','СДЕЛАТЬ','ВОПРОСЫ СПЕЦИАЛИСТУ'].includes(heading(lines[i])))break;const match=lines[i].match(/^\s*[-*•]\s+(.+)/);if(match)result.push(clean(match[1]))}return result},dont=section('НЕ ДЕЛАТЬ'),doList=section('СДЕЛАТЬ'),questions=section('ВОПРОСЫ СПЕЦИАЛИСТУ');
  if(!dont.length||!doList.length||!questions.length)throw Error('Нужны три списка: «НЕ ДЕЛАТЬ», «СДЕЛАТЬ» и «ВОПРОСЫ СПЕЦИАЛИСТУ».');
  return{rows,dont,doList,questions};
}
function renderSecurity(){
  const scenario=securityScenarios[state.securityScenario],promptConfig={id:'safe-prompt-composer',title:'Предварительная оценка допустимости',template:`Вы — помощник по предварительной оценке информационной безопасности в российском государственном секторе. Это учебная самопроверка, а не окончательное юридическое заключение. Участник описывает рабочее намерение и не обязан заранее знать категорию сведений. Самостоятельно определите наиболее вероятную категорию и уровень значимости по составу данных, объёму, способу передачи и цели. Используйте актуальные на 9 октября 2026 года требования: 149-ФЗ, 152-ФЗ, постановление Правительства РФ № 1119, приказ ФСТЭК России № 117 в действующей редакции и специальные режимы, если они применимы. Не считайте сервис допустимым только по названию или стране поставщика. В колонке «Категория сведений» используйте точный правовой термин: сведения о прямо или косвенно определённом физическом лице называйте «персональные данные», сведения о здоровье — «специальные категории персональных данных»; не заменяйте эти термины общими словами «конфиденциальные» или «секретные». При неопределённости выбирайте более строгий маршрут и формулируйте вопросы уполномоченному специалисту.\n\nРабочая задача: [[situation]]\nСостав сведений: [[data]]\nОбъём и регулярность: [[volume]]\nКуда и как предполагается передать сведения: [[transfer]]\nЦель и использование результата: [[purpose]]\nЧто пока не установлено: [[unknowns]]\n\nВерните только две Markdown-таблицы без заголовков и пояснений. Первая таблица должна содержать РОВНО ОДНУ строку результата по описанной ситуации. Вторая таблица должна содержать минимум по одной строке каждого из трёх разделов, даже если ситуация кажется допустимой. Не добавляйте другие разделы. Используйте буквально этот каркас и замените только текст в угловых скобках:\n\n| Уровень | Категория сведений | Значимость | Допустимый контур | Передача | Хранение | Решение | Нормативное основание |\n|---|---|---|---|---|---|---|---|\n| <один уровень> | <одна категория> | <значимость> | <контур> | <передача> | <хранение> | <решение> | <основание> |\n\n| Раздел | Пункт |\n|---|---|\n| НЕ ДЕЛАТЬ | <минимум один конкретный запрет> |\n| СДЕЛАТЬ | <минимум одно конкретное действие> |\n| ВОПРОСЫ СПЕЦИАЛИСТУ | <минимум один конкретный вопрос> |\n\nНе придумывайте согласования и свойства сервиса.`,fields:[{key:'situation',label:'Рабочая задача',elementId:'safe-situation'},{key:'data',label:'Состав сведений',elementId:'safe-data'},{key:'volume',label:'Объём и регулярность',elementId:'safe-volume'},{key:'transfer',label:'Способ передачи',elementId:'safe-transfer'},{key:'purpose',label:'Цель и использование',elementId:'safe-purpose'},{key:'unknowns',label:'Неустановленные условия',elementId:'safe-unknowns'}]};
  el('stage').innerHTML=header(7,'Сначала распознайте сведения, затем выбирайте контур','Участник начинает с обычной рабочей задачи. Категорию, условия допустимости и маршрут согласования нужно определить по фактам, а не по готовой подсказке.')+`<div class="stage-body"><div class="safety-note"><b>Работайте только с обучающими примерами.</b><span>Не вводите реальные сведения. Оцените состав данных, объём, способ передачи, цель и неизвестные условия до использования любого сервиса.</span></div><div class="scenario-tabs">${Object.entries(securityScenarios).map(([key,value])=>`<button data-security="${key}" class="${key===state.securityScenario?'active':''}"><span></span>${value.label}</button>`).join('')}</div><div class="two"><section class="panel warm"><h3>1. Разберите жизненную ситуацию</h3><label class="field"><b>Рабочая задача</b><textarea id="safe-situation">${esc(scenario.situation)}</textarea></label><label class="field"><b>Какие сведения предполагается использовать</b><textarea id="safe-data">${esc(scenario.data)}</textarea></label><label class="field"><b>Объём и регулярность</b><textarea id="safe-volume">${esc(scenario.volume)}</textarea></label><label class="field"><b>Куда и как предполагается передать сведения</b><textarea id="safe-transfer">${esc(scenario.transfer)}</textarea></label><label class="field"><b>Цель и использование результата</b><textarea id="safe-purpose">${esc(scenario.purpose)}</textarea></label><label class="field"><b>Что пока не установлено</b><textarea id="safe-unknowns">${esc(scenario.unknowns)}</textarea></label>${PromptComposer.markup(promptConfig)}</section><section class="panel"><h3>2. Вставьте Markdown и извлеките заключение</h3><textarea id="safe-response" class="response tall" placeholder="Вставьте ответ ИИ-сервиса в формате Markdown"></textarea><div class="actions"><button class="button" id="safe-build">Извлечь заключение</button><button class="button secondary" id="safe-example">Учебный ответ</button></div><div id="safe-status" class="status"></div><div id="safe-artifact"></div></section></div>${methodCard('Правила использования результата',`<p>Матрица предназначена для предварительной учебной самопроверки. Она не устанавливает категорию защищённости, не разрешает передачу сведений и не заменяет решение обладателя информации, оператора персональных данных, подразделения информационной безопасности или юриста.</p><p><b>Внешний, в том числе иностранный, сервис</b> не становится автоматически допустимым или запрещённым только из-за страны поставщика. Для работы исключительно с открытыми сведениями его можно рассматривать после проверки условий сервиса и локальных правил. При наличии персональных данных или сведений ограниченного доступа отдельно проверяются правовое основание, договор, размещение, передача, доступ, хранение и удаление; до этой проверки сведения не передаются.</p><p>Для государственной информационной системы учитывайте приказ ФСТЭК России № 117, вступивший в силу 1 марта 2026 года, в действующей редакции. Для персональных данных отдельно проверяются основания обработки и требования к защите.</p>`,[{label:'Официальный портал правовой информации',url:'https://pravo.gov.ru/'},{label:'152-ФЗ «О персональных данных» — Минтруд России',url:'https://mintrud.gov.ru/docs/laws/130'},{label:'149-ФЗ «Об информации…»',url:'https://www.consultant.ru/document/cons_doc_LAW_61798/'},{label:'Постановление Правительства РФ № 1119',url:'https://www.consultant.ru/document/cons_doc_LAW_137356/'},{label:'Приказ ФСТЭК России № 117 — официальное опубликование',url:'https://publication.pravo.gov.ru/document/0001202506170011'}])}</div>`;
  document.querySelectorAll('[data-security]').forEach(button=>button.onclick=()=>{state.securityScenario=button.dataset.security;render()});PromptComposer.bind(promptConfig.id);el('safe-example').onclick=()=>{el('safe-response').value=securityExample(scenario)};el('safe-build').onclick=()=>{try{const d=parseSecurityMarkdown(el('safe-response').value);el('safe-artifact').innerHTML=`<div class="security-result"><div class="route-legend"><div class="green"><span></span><b>Можно продолжить</b><small>Только открытые сведения; условия сервиса и локальные правила проверены.</small></div><div class="amber"><span></span><b>Только при выполнении условий</b><small>Нужны подтверждённые основание, контур и порядок обработки.</small></div><div class="red"><span></span><b>Остановиться и согласовать</b><small>Передача не начинается до решения уполномоченного специалиста.</small></div></div>${d.rows.map(row=>{const route=securityRoute(row['Решение']);return `<article class="security-card ${route.tone}"><header><span></span><div><small>${esc(row['Уровень'])} · ${esc(row['Значимость'])}</small><b>${route.label}</b><em>${esc(row['Решение'])}</em></div></header><dl><div><dt>Сведения</dt><dd>${esc(row['Категория сведений'])}</dd></div><div><dt>Контур</dt><dd>${esc(row['Допустимый контур'])}</dd></div><div><dt>Передача</dt><dd>${esc(row['Передача'])}</dd></div><div><dt>Хранение</dt><dd>${esc(row['Хранение'])}</dd></div><div><dt>Основание</dt><dd>${esc(row['Нормативное основание'])}</dd></div></dl></article>`}).join('')}<div class="decision-lists"><section class="dont"><h4>Не делать</h4>${d.dont.map(x=>`<p>${esc(x)}</p>`).join('')}</section><section class="do"><h4>Сделать</h4>${d.doList.map(x=>`<p>${esc(x)}</p>`).join('')}</section></div><section class="questions"><h4>Вопросы уполномоченному специалисту</h4>${d.questions.map(x=>`<p>${esc(x)}</p>`).join('')}</section></div>`;el('safe-status').textContent='Предварительное заключение извлечено. Требуется проверка уполномоченного специалиста.';el('safe-status').className='status ok'}catch(e){el('safe-status').textContent=e.message;el('safe-status').className='status bad'}};
}

function renderPilot(){
  const promptConfig={id:'pilot-prompt-composer',title:'Паспорт, подрядчик и защита пилота',template:`Подготовьте паспорт ограниченного пилота, вопросы к подрядчику и содержание презентации защиты из шести слайдов.\n\nПроблема и подтверждённый факт: [[problem]]\nДанные и допустимый контур: [[data]]\nРоль ИИ и контроль человека: [[role]]\nТестовый набор и метрика: [[test]]\nПриёмка и стоп-условия: [[accept]]\n\nНе добавляйте неподтверждённые сведения. Финансовая окупаемость не является обязательным критерием: используйте качество государственной услуги, управляемость и безопасность. Верните только JSON: {"passport":{"problem":"...","confirmed_fact":"...","data":"...","scope":"...","ai_role":"...","human_control":"...","test_set":"...","metric":"...","acceptance":"...","stop_conditions":["..."]},"contractor_questions":["..."],"slides":[{"title":"...","key_message":"..."}]}`,fields:[{key:'problem',label:'Проблема и подтверждённый факт',elementId:'pilot-problem'},{key:'data',label:'Данные и контур',elementId:'pilot-data'},{key:'role',label:'Роль ИИ и контроль человека',elementId:'pilot-role'},{key:'test',label:'Тестовый набор и метрика',elementId:'pilot-test'},{key:'accept',label:'Приёмка и стоп-условия',elementId:'pilot-accept'}]};
  el('stage').innerHTML=header(9,'Паспорт пилота превращается в презентацию защиты','ИИ возвращает строгий JSON; тренажёр строит карточку пилота, чек-лист подрядчика и шесть слайдов по заданному шаблону.')+`<div class="stage-body two"><section class="panel"><h3>1. Заполните поля ограниченного пилота</h3><label class="field"><b>Проблема и подтверждённый факт</b><textarea id="pilot-problem">Проблема: сотрудник тратит время на первичную группировку. Подтверждённый факт: на учебной выборке из 100 обращений требуется проверить точность предварительной классификации.</textarea></label><label class="field"><b>Данные и допустимый контур</b><textarea id="pilot-data">100 обезличенных учебных обращений; работа только в согласованном учебном контуре.</textarea></label><label class="field"><b>Роль ИИ и контроль человека</b><textarea id="pilot-role">ИИ предлагает категорию и обоснование; сотрудник утверждает каждый маршрут.</textarea></label><label class="field"><b>Тестовый набор и метрика</b><textarea id="pilot-test">Заранее размеченные 100 обращений; метрика — доля верных предложений и доля случаев, направленных на проверку.</textarea></label><label class="field"><b>Приёмка и стоп-условия</b><textarea id="pilot-accept">Приёмка — согласованный порог качества на тестовом наборе. Стоп — обнаружение закрытых сведений, отсутствие журнала или невозможность объяснить маршрут.</textarea></label>${PromptComposer.markup(promptConfig)}</section><section class="panel soft"><h3>2. JSON → комплект защиты</h3><textarea id="pilot-response" class="response tall" placeholder="Вставьте JSON из ИИ-сервиса"></textarea><div class="actions"><button class="button" id="pilot-build">Создать комплект</button><button class="button secondary" id="pilot-example">Учебный ответ</button></div><div id="pilot-status" class="status"></div><div id="pilot-artifact"></div><div id="pilot-deck" class="deck"></div></section></div>`;
  PromptComposer.bind(promptConfig.id);el('pilot-example').onclick=()=>{el('pilot-response').value=JSON.stringify({passport:{problem:'сократить время первичной группировки обращений',confirmed_fact:'качество предварительной классификации ещё не проверено на согласованном тестовом наборе',data:'100 обезличенных учебных обращений',scope:'согласованный учебный контур без реальных персональных и закрытых сведений',ai_role:'предложить категорию и краткое основание',human_control:'сотрудник утверждает каждый маршрут',test_set:'100 заранее размеченных обращений',metric:'доля верных предложений и доля эскалаций',acceptance:'выполнены согласованные пороги качества, воспроизводимости и безопасности',stop_conditions:['обнаружены закрытые сведения','нет журнала решений','невозможно объяснить предложенный маршрут']},contractor_questions:['где обрабатываются и хранятся запросы и ответы?','как разграничены права доступа и выгружается журнал?','как удаляются данные и подтверждается выполнение требований?'],slides:[{title:'Проблема и факт',key_message:'Проверяем один подтверждённый узкий процесс.'},{title:'Границы пилота',key_message:'100 обезличенных учебных обращений в согласованном контуре.'},{title:'Роль ИИ',key_message:'Предложить категорию и основание без окончательного решения.'},{title:'Контроль',key_message:'Сотрудник утверждает каждый маршрут; действия журналируются.'},{title:'Приёмка',key_message:'Качество проверяется на заранее размеченном наборе.'},{title:'Решение',key_message:'Масштабирование возможно только после выполнения условий.'}]},null,2)};el('pilot-build').onclick=()=>{try{const d=parseJson(el('pilot-response').value);requireKeys(d,['passport','contractor_questions','slides']);requireKeys(d.passport||{},['problem','confirmed_fact','data','scope','ai_role','human_control','test_set','metric','acceptance','stop_conditions']);requireList(d.passport,'stop_conditions');requireList(d,'contractor_questions');requireRows(d,'slides',['title','key_message']);if(d.slides.length!==6)throw Error('Поле «slides» должно содержать ровно шесть слайдов.');const p=d.passport;el('pilot-artifact').innerHTML=`<article class="pilot-passport"><header><small>ПАСПОРТ ОГРАНИЧЕННОГО ПИЛОТА</small><b>${esc(p.problem)}</b></header><dl><div><dt>Подтверждённый факт</dt><dd>${esc(p.confirmed_fact)}</dd></div><div><dt>Данные и контур</dt><dd>${esc(p.data)} · ${esc(p.scope)}</dd></div><div><dt>Роль ИИ</dt><dd>${esc(p.ai_role)}</dd></div><div><dt>Контроль человека</dt><dd>${esc(p.human_control)}</dd></div><div><dt>Тест и метрика</dt><dd>${esc(p.test_set)} · ${esc(p.metric)}</dd></div><div><dt>Приёмка</dt><dd>${esc(p.acceptance)}</dd></div></dl><section><h4>Стоп-условия</h4>${p.stop_conditions.map(x=>`<p>${esc(x)}</p>`).join('')}</section></article><article class="contractor-check"><h4>Вопросы к подрядчику</h4>${d.contractor_questions.map((x,i)=>`<p><b>${String(i+1).padStart(2,'0')}</b>${esc(x)}</p>`).join('')}</article><h3 class="deck-heading">3. Презентация для защиты участником</h3>`;el('pilot-deck').innerHTML=d.slides.map((s,i)=>`<article class="slide-card"><small>${String(i+1).padStart(2,'0')} · ПРОЕКТ</small><b>${esc(s.title)}</b>${esc(s.key_message)}</article>`).join('');el('pilot-status').textContent='Паспорт, чек-лист и презентация сформированы по шаблону';el('pilot-status').className='status ok'}catch(e){el('pilot-status').textContent=e.message;el('pilot-status').className='status bad'}};
}

const renders=[renderMetric,renderPeriod,renderSeason,renderForecast,renderExperiment,renderClassification,renderSecurity,renderAutomationLocalized,renderPilot];
function render(){history.replaceState(null,'',location.pathname+'?step='+(state.step+1));el('journey').innerHTML=steps.map((s,i)=>`<button data-step="${i}" class="${i===state.step?'active':i<state.step?'done':''}"><small>Занятие ${s[2]}</small><span>${String(i+1).padStart(2,'0')}</span>${s[0]}</button>`).join('');document.querySelectorAll('[data-step]').forEach(b=>b.onclick=()=>{state.step=+b.dataset.step;render();window.scrollTo({top:document.querySelector('.course').offsetTop,behavior:'smooth'})});renders[state.step]();el('prev').disabled=state.step===0;el('next').disabled=state.step===steps.length-1;el('position').textContent=`Занятие ${steps[state.step][2]} · шаг ${state.step+1} из ${steps.length}`;el('next-title').textContent=state.step<steps.length-1?'Далее: '+steps[state.step+1][0]:'Практикум завершён'}
el('prev').onclick=()=>{if(state.step>0){state.step--;render();window.scrollTo({top:document.querySelector('.course').offsetTop,behavior:'smooth'})}};el('next').onclick=()=>{if(state.step<steps.length-1){state.step++;render();window.scrollTo({top:document.querySelector('.course').offsetTop,behavior:'smooth'})}};
Promise.all([fetch('data/jti-reference.json').then(r=>r.json()),fetch('data/government-seasonality.json').then(r=>r.json())]).then(([jti,gov])=>{state.jti=jti;state.gov=gov;render()}).catch(e=>{el('stage').innerHTML=header(0,'Не удалось загрузить проверенные данные',esc(e.message));});
